import os
import base64
from openai import OpenAI

def describe_image(payload, config=None):
    config = config or {}
    client = OpenAI(api_key=config.get("api_key") or os.environ.get("OPENAI_API_KEY"))
    image_input = payload
    if isinstance(payload, dict):
        image_input = payload.get("image") or payload.get("image_url") or payload.get("url") or payload.get("data")
    if not image_input:
        raise ValueError("payload must contain an image, image_url, url, or data value")

    if isinstance(image_input, bytes):
        image_url = f"data:image/jpeg;base64,{base64.b64encode(image_input).decode('utf-8')}"
    elif isinstance(image_input, str) and os.path.exists(image_input):
        with open(image_input, "rb") as f:
            image_url = f"data:image/jpeg;base64,{base64.b64encode(f.read()).decode('utf-8')}"
    elif isinstance(image_input, str):
        image_url = image_input
    else:
        raise TypeError("Unsupported image payload type")

    result = client.responses.create(
        model=config.get("model", "gpt-4.1-mini"),
        input=[{
            "role": "user",
            "content": [
                {"type": "input_text", "text": config.get("prompt", "Give a short visual description of this image.")},
                {"type": "input_image", "image_url": image_url},
            ],
        }]
    ).output_text
    return result
